def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_aggressive = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev['bid']
                prev_bids.append(bid)
                if opp.get('budget', 0) > DAILY_SALARY * 8 and bid >= DAILY_SALARY * 0.8:
                    rich_aggressive += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    base = DAILY_SALARY * (0.42 + 0.28 * scarcity)

    if highest_prev >= 120:
        base = max(base, min(highest_prev * 0.72, DAILY_SALARY * 0.95))
    elif highest_prev >= 80:
        base = max(base, min(avg_prev + 3.0, DAILY_SALARY * 0.88))
    elif highest_prev > 0:
        base = max(base, min(highest_prev + 2.0, DAILY_SALARY * 0.78))

    if hp <= 2:
        base = max(base, DAILY_SALARY * 0.97)
    elif hp <= 4:
        base = max(base, DAILY_SALARY * 0.82)
    elif hp >= 8 and no_water_days == 0 and supply >= 22:
        base = min(base, DAILY_SALARY * 0.38)

    if no_water_days >= 2:
        base = max(base, DAILY_SALARY * 0.98)
    elif no_water_days == 1:
        base = max(base, DAILY_SALARY * 0.86)

    if rich_aggressive >= 2 and hp > 4 and no_water_days == 0:
        base = min(base, DAILY_SALARY * 0.45)

    if desperate_count >= 2 and hp > 5 and supply >= 20:
        base = min(base, DAILY_SALARY * 0.4)

    if day >= 8:
        base = max(base, DAILY_SALARY * 0.62)
    if day >= 9 and hp <= 5:
        base = max(base, DAILY_SALARY * 0.9)

    bid = min(budget, base)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids only from previous_trace (immediate reaction)
    prev_bids = []
    prev_hp_after = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass
        if prev.get('hp_after') is not None:
            try:
                prev_hp_after.append(float(prev['hp_after']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Estimate required aggressiveness: if someone bid high yesterday, match; if bids were low, slightly overcut.
    # Also react to my own hp/no-water pressure.
    pressure = 0.0
    if hp <= 2:
        pressure += 1.0
    if no_water_days >= 2:
        pressure += 0.7
    if hp <= 0:
        pressure += 2.0

    # Supply factor: more supply means water is easier; bid lower.
    # Ensure indices are integer-safe if we used arrays; here we just compute thresholds.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base bid target
    # If yesterday's highest bid was strong, we need to contest.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base = DAILY_SALARY * (0.65 + 0.25 * pressure)
        target = max(base, highest_prev_bid + 2.0)
    else:
        # If highest bid was not that high, exploit underbidding: bid just above avg/highest.
        target = max(avg_prev_bid + 3.0, highest_prev_bid + 2.0)
        # Adjust for my pressure and supply
        target *= (0.85 + 0.25 * pressure)
        target *= (0.95 - 0.15 * supply_ratio)

    # Clamp to budget and practical bounds
    target = max(0.0, target)

    # If my hp is critical, spend more (but never exceed budget)
    if hp <= 3:
        target = max(target, DAILY_SALARY * 0.9)

    # If I have plenty of budget and early/mid game, be slightly more aggressive
    if day <= 5 and budget > DAILY_SALARY * 1.2:
        target *= 1.05

    bid = min(budget, target)

    # Ensure we never bid negative and keep at least a small amount if budget allows
    if bid < 1e-6:
        bid = min(budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
